_choice_cloc_command() {
    _argc_util_comp_command
}

_choice_cloc_encoding() {
    perl -MEncode -e 'print join("\n", Encode->encodings(":all")), "\n"' 2>/dev/null
}

_choice_cloc_ext() {
    cloc --show-ext 2>/dev/null | gawk 'NR > 2 { print $1 }'
}

_choice_cloc_lang() {
    cloc --show-lang 2>/dev/null | gawk '
        NR > 2 {
            line = $0
            sub(/[[:space:]]*\(.*/, "", line)
            gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
            if (length(line)) print line
        }
    '
}

_choice_sql_style() {
    printf 'Oracle\n'
    printf 'Named_Columns\n'
}

_choice_summary_cutoff() {
    [[ "${ARGC_LAST_ARG:-}" == *:* ]] && return 0
    printf 'c\tlines of code\n'
    printf 'f\tfiles\n'
    printf 'm\tlines of comments\n'
    printf 'cm\tlines of code + comments\n'
}
